-- Cauri Charts : schéma PostgreSQL (traduction fidèle de database/schema.sql, MySQL).
-- Mêmes tables, colonnes, valeurs par défaut, contraintes et index. ENUM MySQL → VARCHAR + CHECK.
-- Identifiants GENERATED BY DEFAULT : permet de reprendre les identifiants existants lors de la migration.

DROP TABLE IF EXISTS social_posts, partners, chart_observations, news, contact_messages, api_quota, audit_log, login_attempts, users,
    track_reviews, weekly_scores, chart_entries, chart_runs, chart_types, formula_versions,
    submissions, snapshots, track_platform_ids, tracks, artists, countries CASCADE;

-- Comparaisons et tris insensibles à la casse et aux accents, comme la collation utf8mb4_unicode_ci de MariaDB
-- (Ø est une lettre à part, après O, comme dans l'algorithme UCA 4.0 de MariaDB)
CREATE COLLATION IF NOT EXISTS cauri_ci (provider = icu, locale = 'und-u-ks-level1', rules = U&'&O < \00F8 <<< \00D8', deterministic = false);

CREATE TABLE countries (
    id           SMALLINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code         CHAR(2)      NOT NULL UNIQUE,
    name_fr      VARCHAR(80)  NOT NULL,
    name_en      VARCHAR(80)  NOT NULL,
    locale       VARCHAR(5)   NOT NULL DEFAULT 'fr',
    chart_size   SMALLINT     NOT NULL DEFAULT 10,
    platforms    VARCHAR(255) NOT NULL DEFAULT 'youtube',
    is_active    SMALLINT     NOT NULL DEFAULT 1,
    is_pilot     SMALLINT     NOT NULL DEFAULT 0,
    sort_order   SMALLINT     NOT NULL DEFAULT 0,
    created_at   TIMESTAMP(0) NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE artists (
    id                     INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name                   VARCHAR(150) NOT NULL,
    slug                   VARCHAR(160) NOT NULL UNIQUE,
    submission_country_id  SMALLINT NOT NULL REFERENCES countries(id),
    label_owner            VARCHAR(50)  NULL,
    is_emerging            SMALLINT     NOT NULL DEFAULT 0,
    status                 VARCHAR(12)  NOT NULL DEFAULT 'active' CHECK (status IN ('active','pending','out_of_scope')),
    guessed_country_id     SMALLINT NULL,
    match_key              VARCHAR(160) NULL,
    top_country_id         SMALLINT NULL REFERENCES countries(id),
    top_country_share      NUMERIC(5,2) NULL,
    top_country_updated_at DATE NULL,
    bio                    TEXT NULL,
    image_url              VARCHAR(500) NULL,
    image_hd_url           VARCHAR(500) NULL,
    image_source           VARCHAR(20)  NULL,
    image_locked           SMALLINT     NOT NULL DEFAULT 0,
    apple_id               BIGINT       NULL,
    photo_checked_at       TIMESTAMP(0) NULL,
    photo_candidates       TEXT NULL,
    image_credit           VARCHAR(250) NULL,
    deezer_id              BIGINT NULL,
    spotify_id             VARCHAR(40) NULL,
    fans                   INTEGER NULL,
    youtube_channel_id     VARCHAR(40) NULL,
    youtube_subscribers    INTEGER NULL,
    youtube_views_total    BIGINT NULL,
    channel_checked_at     TIMESTAMP(0) NULL,
    discovered_via         VARCHAR(160) NULL,
    profile_checked_at     TIMESTAMP(0) NULL,
    origin_country         CHAR(2) NULL,
    base_country           CHAR(2) NULL,
    origin_source          VARCHAR(20) NULL,
    origin_confidence      NUMERIC(3,2) NULL,
    origin_note            VARCHAR(1000) NULL,
    origin_checked_at      TIMESTAMP(0) NULL,
    created_at             TIMESTAMP(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at             TIMESTAMP(0) NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX idx_artist_country ON artists (submission_country_id);
CREATE INDEX idx_artist_match ON artists (match_key);
CREATE INDEX idx_artist_status ON artists (status);

-- Équivalent de « ON UPDATE CURRENT_TIMESTAMP » (MySQL)
CREATE OR REPLACE FUNCTION touch_updated_at() RETURNS trigger AS $$
BEGIN NEW.updated_at := CURRENT_TIMESTAMP; RETURN NEW; END; $$ LANGUAGE plpgsql;
CREATE TRIGGER artists_updated_at BEFORE UPDATE ON artists FOR EACH ROW EXECUTE FUNCTION touch_updated_at();

CREATE TABLE tracks (
    id            INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    title         VARCHAR(200) NOT NULL,
    slug          VARCHAR(220) NOT NULL UNIQUE,
    artist_id     INTEGER NOT NULL REFERENCES artists(id),
    featuring     VARCHAR(255) NULL,
    release_date  DATE NULL,
    cover_url     VARCHAR(500) NULL,
    is_active     SMALLINT NOT NULL DEFAULT 1,
    match_key     VARCHAR(255) NULL,
    youtube_checked_at TIMESTAMP(0) NULL,
    created_at    TIMESTAMP(0) NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX idx_track_artist ON tracks (artist_id);
CREATE INDEX idx_track_match ON tracks (match_key);

CREATE TABLE track_platform_ids (
    id            INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    track_id      INTEGER NOT NULL REFERENCES tracks(id) ON DELETE CASCADE,
    platform      VARCHAR(11) NOT NULL CHECK (platform IN ('youtube','audiomack','boomplay','spotify','apple_music','deezer')),
    external_id   VARCHAR(191) NOT NULL,
    kind          VARCHAR(30)  NOT NULL DEFAULT 'main',
    url           VARCHAR(500) NULL,
    published_at  DATE NULL,
    is_official   SMALLINT NOT NULL DEFAULT 1,
    match_status  VARCHAR(9) NOT NULL DEFAULT 'manual' CHECK (match_status IN ('manual','auto','confirmed')),
    CONSTRAINT uq_platform_external UNIQUE (platform, external_id)
);
CREATE INDEX idx_tpi_track ON track_platform_ids (track_id);

CREATE TABLE snapshots (
    id                 BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    track_platform_id  INTEGER NOT NULL REFERENCES track_platform_ids(id) ON DELETE CASCADE,
    captured_on        DATE NOT NULL,
    plays              BIGINT NOT NULL,
    likes              BIGINT NULL,
    comments           BIGINT NULL,
    popularity         SMALLINT NULL,
    source             VARCHAR(6) NOT NULL DEFAULT 'api' CHECK (source IN ('api','manual')),
    created_by         INTEGER NULL,
    created_at         TIMESTAMP(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uq_snap_day UNIQUE (track_platform_id, captured_on)
);
CREATE INDEX idx_snap_day ON snapshots (captured_on);

CREATE TABLE submissions (
    id                     INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    track_id               INTEGER NULL REFERENCES tracks(id) ON DELETE SET NULL,
    artist_id              INTEGER NULL REFERENCES artists(id) ON DELETE SET NULL,
    submitted_artist_name  VARCHAR(150) NOT NULL,
    submitted_track_title  VARCHAR(200) NOT NULL,
    contact_name           VARCHAR(150) NOT NULL,
    contact_email          VARCHAR(190) NOT NULL,
    platform               VARCHAR(30)  NOT NULL,
    period_start           DATE NOT NULL,
    period_end             DATE NOT NULL,
    streams                BIGINT NOT NULL,
    country_breakdown      TEXT NULL,
    screenshot_path        VARCHAR(255) NOT NULL,
    status                 VARCHAR(9) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','validated','rejected')),
    reviewed_by            INTEGER NULL,
    reviewed_at            TIMESTAMP(0) NULL,
    review_note            TEXT NULL,
    ip_hash                CHAR(64) NULL,
    created_at             TIMESTAMP(0) NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX idx_sub_status ON submissions (status);
CREATE INDEX idx_sub_track_period ON submissions (track_id, period_start, period_end);

CREATE TABLE formula_versions (
    id              INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    version         INTEGER NOT NULL UNIQUE,
    formula_json    TEXT NOT NULL,
    effective_from  DATE NOT NULL,
    note            VARCHAR(500) NULL,
    created_by      INTEGER NULL,
    created_at      TIMESTAMP(0) NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE chart_types (
    id            SMALLINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code          VARCHAR(30) NOT NULL UNIQUE,
    name          VARCHAR(100) NOT NULL,
    kind          VARCHAR(7) NOT NULL DEFAULT 'tracks' CHECK (kind IN ('tracks','artists')),
    is_public     SMALLINT NOT NULL DEFAULT 0,
    is_computed   SMALLINT NOT NULL DEFAULT 0,
    is_regional   SMALLINT NOT NULL DEFAULT 0,
    sort_order    SMALLINT NOT NULL DEFAULT 0
);

CREATE TABLE chart_runs (
    id                   INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    chart_type_id        SMALLINT NOT NULL REFERENCES chart_types(id),
    country_id           SMALLINT NULL REFERENCES countries(id),
    period_type          VARCHAR(5) NOT NULL CHECK (period_type IN ('week','month','year')),
    period_key           VARCHAR(10) NOT NULL,
    period_start         DATE NOT NULL,
    period_end           DATE NOT NULL,
    formula_version      INTEGER NOT NULL,
    formula_json         TEXT NOT NULL,
    methodology_version  VARCHAR(10) NOT NULL,
    status               VARCHAR(9) NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','published')),
    is_provisional       SMALLINT NOT NULL DEFAULT 0,
    computed_at          TIMESTAMP(0) NOT NULL,
    published_at         TIMESTAMP(0) NULL,
    published_by         INTEGER NULL,
    correction_note      TEXT NULL,
    corrected_at         TIMESTAMP(0) NULL,
    -- Classement régional (country_id NULL) : unicité garantie aussi (PostgreSQL 15+)
    CONSTRAINT uq_run UNIQUE NULLS NOT DISTINCT (chart_type_id, country_id, period_type, period_key)
);
CREATE INDEX idx_run_lookup ON chart_runs (country_id, period_type, status, period_end);

CREATE TABLE chart_entries (
    id                 BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    chart_run_id       INTEGER NOT NULL REFERENCES chart_runs(id) ON DELETE CASCADE,
    position           SMALLINT NOT NULL,
    track_id           INTEGER NULL REFERENCES tracks(id),
    artist_id          INTEGER NULL REFERENCES artists(id),
    score              NUMERIC(18,2) NOT NULL,
    previous_position  SMALLINT NULL,
    peak_position      SMALLINT NOT NULL,
    weeks_on_chart     SMALLINT NOT NULL DEFAULT 1,
    sources_count      SMALLINT NOT NULL DEFAULT 0,
    growth_pct         NUMERIC(10,2) NULL,
    flags              TEXT NULL,
    details            TEXT NULL,
    CONSTRAINT uq_entry_pos UNIQUE (chart_run_id, position)
);
CREATE INDEX idx_entry_track ON chart_entries (track_id);
CREATE INDEX idx_entry_artist ON chart_entries (artist_id);

CREATE TABLE weekly_scores (
    id               BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    track_id         INTEGER NOT NULL REFERENCES tracks(id),
    country_id       SMALLINT NOT NULL REFERENCES countries(id),
    week_start       DATE NOT NULL,
    score            NUMERIC(18,2) NOT NULL,
    sources_count    SMALLINT NOT NULL,
    breakdown        TEXT NOT NULL,
    flags            TEXT NOT NULL,
    review_status    VARCHAR(9) NOT NULL DEFAULT 'ok' CHECK (review_status IN ('ok','pending','validated','excluded')),
    formula_version  INTEGER NOT NULL,
    computed_at      TIMESTAMP(0) NOT NULL,
    CONSTRAINT uq_ws UNIQUE (track_id, week_start)
);
CREATE INDEX idx_ws_country_week ON weekly_scores (country_id, week_start);

CREATE TABLE track_reviews (
    id          INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    track_id    INTEGER NOT NULL REFERENCES tracks(id),
    week_start  DATE NOT NULL,
    decision    VARCHAR(9) NOT NULL CHECK (decision IN ('validated','excluded')),
    reason      TEXT NOT NULL,
    user_id     INTEGER NOT NULL,
    created_at  TIMESTAMP(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uq_review UNIQUE (track_id, week_start)
);

CREATE TABLE users (
    id             INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    email          VARCHAR(190) NOT NULL UNIQUE,
    name           VARCHAR(150) NOT NULL,
    password_hash  VARCHAR(255) NOT NULL,
    role           VARCHAR(6) NOT NULL DEFAULT 'editor' CHECK (role IN ('admin','editor')),
    totp_secret    VARCHAR(64) NULL,
    is_active      SMALLINT NOT NULL DEFAULT 1,
    last_login_at  TIMESTAMP(0) NULL,
    created_at     TIMESTAMP(0) NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE login_attempts (
    id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ip            VARCHAR(45) NOT NULL,
    email         VARCHAR(190) NOT NULL,
    success       SMALLINT NOT NULL DEFAULT 0,
    attempted_at  TIMESTAMP(0) NOT NULL
);
CREATE INDEX idx_login_ip ON login_attempts (ip, attempted_at);
CREATE INDEX idx_login_email ON login_attempts (email, attempted_at);

CREATE TABLE audit_log (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id      INTEGER NULL,
    action       VARCHAR(60) NOT NULL,
    entity_type  VARCHAR(40) NULL,
    entity_id    VARCHAR(40) NULL,
    reason       TEXT NULL,
    data         TEXT NULL,
    ip           VARCHAR(45) NULL,
    created_at   TIMESTAMP(0) NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX idx_audit_entity ON audit_log (entity_type, entity_id);
CREATE INDEX idx_audit_date ON audit_log (created_at);

CREATE TABLE api_quota (
    api         VARCHAR(30) NOT NULL,
    day         DATE NOT NULL,
    units_used  INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (api, day)
);

CREATE TABLE contact_messages (
    id           INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    type         VARCHAR(12) NOT NULL DEFAULT 'contact' CHECK (type IN ('contact','contestation','claim')),
    name         VARCHAR(150) NOT NULL,
    email        VARCHAR(190) NOT NULL,
    subject      VARCHAR(200) NOT NULL,
    message      TEXT NOT NULL,
    status       VARCHAR(8) NOT NULL DEFAULT 'new' CHECK (status IN ('new','answered','closed')),
    ip_hash      CHAR(64) NULL,
    created_at   TIMESTAMP(0) NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE news (
    id            INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    title         VARCHAR(200) NOT NULL,
    slug          VARCHAR(220) NOT NULL UNIQUE,
    summary       VARCHAR(400) NOT NULL,
    body          TEXT NULL,
    category      VARCHAR(10) NOT NULL DEFAULT 'annonce' CHECK (category IN ('annonce','classement','sortie','evenement','industrie')),
    country_id    SMALLINT NULL REFERENCES countries(id) ON DELETE SET NULL,
    source_name   VARCHAR(120) NULL,
    source_url    VARCHAR(500) NULL,
    image_path    VARCHAR(120) NULL,
    origin        VARCHAR(6) NOT NULL DEFAULT 'manual' CHECK (origin IN ('manual','feed')),
    external_guid VARCHAR(191) NULL UNIQUE,
    status        VARCHAR(9) NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','published')),
    published_at  TIMESTAMP(0) NULL,
    created_by    INTEGER NULL,
    created_at    TIMESTAMP(0) NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX idx_news_pub ON news (status, published_at);

CREATE TABLE social_posts (
    id            INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    slot_date     DATE NOT NULL,
    theme         VARCHAR(30) NOT NULL,
    title         VARCHAR(160) NOT NULL,
    caption       TEXT NOT NULL,
    hashtags      VARCHAR(300) NULL,
    facts         TEXT NOT NULL,
    image_square  VARCHAR(120) NULL,
    image_story   VARCHAR(120) NULL,
    carousel      TEXT NULL,
    video         VARCHAR(120) NULL,
    status        VARCHAR(9) NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','approved','published','rejected')),
    created_at    TIMESTAMP(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uq_post_slot UNIQUE (slot_date, theme)
);

CREATE TABLE partners (
    id           SMALLINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name         VARCHAR(120) NOT NULL,
    url          VARCHAR(300) NULL,
    tier         VARCHAR(11) NOT NULL DEFAULT 'officiel' CHECK (tier IN ('officiel','media','plateforme','institution')),
    description  VARCHAR(240) NULL,
    logo_path    VARCHAR(120) NULL,
    sort_order   SMALLINT NOT NULL DEFAULT 0,
    is_active    SMALLINT NOT NULL DEFAULT 1,
    created_at   TIMESTAMP(0) NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE chart_observations (
    id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    source        VARCHAR(30) NOT NULL,
    country_id    SMALLINT NOT NULL REFERENCES countries(id),
    observed_on   DATE NOT NULL,
    position      SMALLINT NOT NULL,
    track_id      INTEGER NOT NULL REFERENCES tracks(id) ON DELETE CASCADE,
    raw_title     VARCHAR(255) NOT NULL,
    raw_artist    VARCHAR(255) NOT NULL,
    created_at    TIMESTAMP(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uq_obs UNIQUE (source, country_id, observed_on, position)
);
CREATE INDEX idx_obs_track_day ON chart_observations (track_id, observed_on);
CREATE INDEX idx_obs_day ON chart_observations (observed_on, source, country_id);
-- Analyses : statistiques des publications, vues du site (anonymes, agrégées), historique des nuits. Ajouts seulement.
CREATE TABLE IF NOT EXISTS post_metrics (
    buffer_post_id  VARCHAR(40)  NOT NULL,
    captured_on     DATE         NOT NULL,
    social_post_id  INTEGER      NULL,            -- post Cauri d'origine (quand il est connu)
    channel         VARCHAR(20)  NOT NULL,        -- instagram, facebook, tiktok
    post_type       VARCHAR(20)  NULL,            -- post, reel, story
    sent_at         TIMESTAMP(0) NULL,
    metrics         TEXT         NOT NULL,        -- JSON : vues, portée, réactions, commentaires, partages, enregistrements…
    text_start      VARCHAR(300) NULL,
    PRIMARY KEY (buffer_post_id, captured_on)
);
CREATE TABLE IF NOT EXISTS page_views (
    day        DATE         NOT NULL,
    path       VARCHAR(200) NOT NULL,
    referrer   VARCHAR(100) NOT NULL DEFAULT '',  -- domaine d'origine seulement (google.com, instagram.com…)
    views      INTEGER      NOT NULL DEFAULT 0,
    PRIMARY KEY (day, path, referrer)
);
CREATE TABLE IF NOT EXISTS pipeline_runs (
    id        INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ran_at    TIMESTAMP(0) NOT NULL DEFAULT LOCALTIMESTAMP,
    seconds   INTEGER      NOT NULL,
    failed    INTEGER      NOT NULL,
    steps     TEXT         NOT NULL                -- JSON : [étape, réussie, secondes]
);
-- Agents de contrôle : constats de chaque nuit (corrigés automatiquement ou à traiter). Ajout seulement.
CREATE TABLE IF NOT EXISTS agent_findings (
    id       INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ran_at   TIMESTAMP(0) NOT NULL DEFAULT LOCALTIMESTAMP,
    agent    VARCHAR(40)  NOT NULL,
    level    VARCHAR(10)  NOT NULL,       -- corrige, alerte, info
    message  VARCHAR(600) NOT NULL,
    link     VARCHAR(300) NULL
);
-- Actualité des artistes : sorties détectées sur Deezer et faits ajoutés par la rédaction (avec leur source). Ajout seulement.
CREATE TABLE IF NOT EXISTS artist_events (
    id          INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    artist_id   INTEGER      NOT NULL REFERENCES artists(id),
    kind        VARCHAR(20)  NOT NULL,          -- album, ep, single, concert, clip, distinction, autre
    title       VARCHAR(200) NOT NULL,
    event_date  DATE         NOT NULL,
    summary     VARCHAR(500) NULL,
    image_url   VARCHAR(500) NULL,
    source_name VARCHAR(100) NULL,
    source_url  VARCHAR(500) NULL,
    origin      VARCHAR(10)  NOT NULL,          -- deezer (automatique) ou redaction
    external_id VARCHAR(40)  NULL UNIQUE,       -- identifiant Deezer de la sortie
    status      VARCHAR(12)  NOT NULL DEFAULT 'published',
    created_at  TIMESTAMP(0) NOT NULL DEFAULT LOCALTIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_artist_events_date ON artist_events (event_date);

-- Le numéro de la distinction (N° 0001…) est l'identifiant : il ne se réutilise jamais.
CREATE TABLE IF NOT EXISTS award_distinctions (
    id           INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    chart_run_id INTEGER      NOT NULL REFERENCES chart_runs(id),
    scope        VARCHAR(3)   NOT NULL,          -- WA (Afrique de l'Ouest) ou code pays
    period_key   VARCHAR(10)  NOT NULL,          -- 2026-10
    rank         SMALLINT     NOT NULL,
    track_id     INTEGER      NULL REFERENCES tracks(id),
    artist_id    INTEGER      NOT NULL REFERENCES artists(id),
    artist_name  VARCHAR(150) NOT NULL,
    title        VARCHAR(200) NULL,
    chart_label  VARCHAR(80)  NOT NULL,          -- « Top 20 · Afrique de l'Ouest »
    stats        TEXT         NOT NULL DEFAULT '{}',  -- {last, peak, weeks} tirés de chart_entries
    photo_url    VARCHAR(500) NULL,
    image_name   VARCHAR(60)  NULL,              -- media/distinctions/<id>.jpg
    status       VARCHAR(10)  NOT NULL DEFAULT 'new',  -- new, sent
    sent_at      TIMESTAMP(0) NULL,
    created_at   TIMESTAMP(0) NOT NULL DEFAULT LOCALTIMESTAMP,
    CONSTRAINT uq_distinction_rank UNIQUE (chart_run_id, rank)
);
-- Rareté : un titre n'est distingué qu'une fois par classement (Afrique de l'Ouest ou pays)
CREATE UNIQUE INDEX IF NOT EXISTS uq_distinction_track_scope ON award_distinctions (track_id, scope) WHERE track_id IS NOT NULL;
